function P({registerIndicator:g,sourceValues:v,nulls:d}){g({id:"oa-jbands",name:"Jurik Volatility Bands (JBANDS)",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"upper",type:"line",title:"Upper",style:{color:"#ffeb3b",lineWidth:2}},{key:"lower",type:"line",title:"Lower",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["upper","lower"],colorUp:"#2962ff",colorDown:"#2962ff",opacity:.1}],calc(n,b){const l=Math.max(1,Math.floor(Number(b.period)||10)),p=v(n,b.source??"close"),a=n.length,h=Math.max(Math.log(Math.sqrt(.5*(l-1)))/Math.log(2)+2,0),N=Math.max(h-2,.5),w=Math.sqrt(.5*(l-1))*h,L=2/(Math.max(4*l,65)+1),k=1/(10+10*(Math.min(Math.max(l-10,0),100)/100)),O=Math.pow(h,1/N),x=new Array(a).fill(NaN),A=new Array(a).fill(NaN),u=new Array(a).fill(NaN);let e=Number.isFinite(p[0])?p[0]:0,i=e,m=0,o=0;for(let t=0;t<a;t++){const r=n[t].high,s=n[t].low;if(!Number.isFinite(p[t])||!Number.isFinite(r)||!Number.isFinite(s))continue;const F=(s+r)*.5,y=F-e,f=F-i,M=Math.max(Math.abs(y),Math.abs(f));u[t]=M;const B=t>=10&&Number.isFinite(u[t-10])?u[t-10]:0;m=m+(M-B)*k,o=o+L*(m-o);let c=1;o>0&&(c=M/o,c=Math.min(Math.max(c,1),O));const V=Math.pow(w/(w+1),Math.sqrt(Math.pow(c,N)));e=y>0?r:r-V*y,i=f<0?s:s-V*f,!(!Number.isFinite(e)||!Number.isFinite(i))&&(x[t]=e,A[t]=i)}return{upper:d(x),lower:d(A)}}})}export{P as default};
